 1→"use client";
 2→
 3→/**
 4→ * Dashboard route (`/dashboard`).
 5→ *
 6→ * Orchestrates the multi-agent WebSocket hook, sidebar, and chat panel.
 7→ * Clicking "+" or selecting "New Agent" sets `activeAgentId` to `null`,
 8→ * which shows the spawn input. On spawn, the server responds with
 9→ * `spawned` and the hook auto-selects the new agent.
10→ */
11→
12→import { useWebSocket } from "@/hooks/use-websocket";
13→import { AgentSidebar } from "@/components/dashboard/agent-sidebar";
14→import { Chat } from "@/components/dashboard/chat";
15→
16→export default function DashboardPage() {
17→  const {
18→    connected,
19→    agents,
20→    agentOrder,
21→    activeAgentId,
22→    setActiveAgentId,
23→    activeStatus,
24→    activeMessages,
25→    activeRawMessages,
26→    spawnAgent,
27→    sendMessage,
28→    respondToControl,
29→    respondToUserQuestion,
30→    killAgent,
31→    deleteAgent,
32→    renameAgent,
33→    clearHistory,
34→  } = useWebSocket();
35→
36→  return (
37→    <div className="flex h-dvh">
38→      <AgentSidebar
39→        agents={agents}
40→        agentOrder={agentOrder}
41→        activeAgentId={activeAgentId}
42→        onSelect={setActiveAgentId}
43→        onNewAgent={() => setActiveAgentId(null)}
44→        onKill={killAgent}
45→        onDelete={deleteAgent}
46→        onRename={renameAgent}
47→        onClearHistory={clearHistory}
48→      />
49→      <div className="flex flex-1 flex-col">
50→        <Chat
51→          connected={connected}
52→          status={activeStatus}
53→          messages={activeMessages}
54→          rawMessages={activeRawMessages}
55→          onSendMessage={sendMessage}
56→          onSpawnAgent={spawnAgent}
57→          onRespondToControl={respondToControl}
58→          onRespondToUserQuestion={respondToUserQuestion}
59→        />
60→      </div>
61→    </div>
62→  );
63→}
