  1→"use client";
  2→
  3→import { Canvas, useFrame, useThree } from "@react-three/fiber";
  4→import { useCallback, useEffect, useMemo, useRef } from "react";
  5→import * as THREE from "three";
  6→
  7→// ---------- shared vertex shader ----------
  8→const fullscreenVert = /* glsl */ `
  9→  varying vec2 vUv;
 10→  void main() {
 11→    vUv = uv;
 12→    gl_Position = vec4(position, 1.0);
 13→  }
 14→`;
 15→
 16→// ---------- splat shader: adds energy at mouse position ----------
 17→const splatFrag = /* glsl */ `
 18→  precision highp float;
 19→  varying vec2 vUv;
 20→  uniform sampler2D uPrev;
 21→  uniform vec2 uSplatPos;   // mouse position in 0..1 UV
 22→  uniform vec2 uSplatVel;   // mouse velocity (for directional energy)
 23→  uniform float uSplatRadius;
 24→  uniform float uSplatStrength;
 25→  uniform float uDoSplat;    // 1.0 when mouse is moving, 0.0 otherwise
 26→
 27→  void main() {
 28→    vec4 prev = texture2D(uPrev, vUv);
 29→    vec2 diff = vUv - uSplatPos;
 30→    // correct for aspect ratio
 31→    diff.x *= (1.0); // we'll handle aspect in JS by scaling radius
 32→    float dist = dot(diff, diff);
 33→    float splat = exp(-dist / uSplatRadius) * uSplatStrength * uDoSplat;
 34→    // store energy in r, velocity direction in gb
 35→    float energy = prev.r + splat;
 36→    vec2 vel = prev.gb + normalize(uSplatVel + 0.001) * splat * 0.5;
 37→    gl_FragColor = vec4(energy, vel, prev.a);
 38→  }
 39→`;
 40→
 41→// ---------- decay/advect shader: fades + spreads energy ----------
 42→const decayFrag = /* glsl */ `
 43→  precision highp float;
 44→  varying vec2 vUv;
 45→  uniform sampler2D uPrev;
 46→  uniform vec2 uTexelSize;
 47→  uniform float uDecay;
 48→
 49→  void main() {
 50→    vec4 c = texture2D(uPrev, vUv);
 51→
 52→    // light diffusion: mostly keep current value, blend a little with neighbors
 53→    vec4 n = texture2D(uPrev, vUv + vec2(0.0, uTexelSize.y));
 54→    vec4 s = texture2D(uPrev, vUv - vec2(0.0, uTexelSize.y));
 55→    vec4 e = texture2D(uPrev, vUv + vec2(uTexelSize.x, 0.0));
 56→    vec4 w = texture2D(uPrev, vUv - vec2(uTexelSize.x, 0.0));
 57→    vec4 result = c * 0.7 + (n + s + e + w) * 0.075;
 58→    result *= uDecay;
 59→
 60→    gl_FragColor = result;
 61→  }
 62→`;
 63→
 64→// ---------- main display shader ----------
 65→const displayFrag = /* glsl */ `
 66→  precision highp float;
 67→
 68→  varying vec2 vUv;
 69→  uniform float uTime;
 70→  uniform vec2 uResolution;
 71→  uniform sampler2D uEnergyTex;
 72→
 73→  // --- noise helpers ---
 74→  float hash(vec2 p) {
 75→    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
 76→  }
 77→
 78→  float noise(vec2 p) {
 79→    vec2 i = floor(p);
 80→    vec2 f = fract(p);
 81→    f = f * f * (3.0 - 2.0 * f);
 82→    float a = hash(i);
 83→    float b = hash(i + vec2(1.0, 0.0));
 84→    float c = hash(i + vec2(0.0, 1.0));
 85→    float d = hash(i + vec2(1.0, 1.0));
 86→    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
 87→  }
 88→
 89→  float fbm(vec2 p) {
 90→    float v = 0.0;
 91→    float a = 0.5;
 92→    vec2 shift = vec2(100.0);
 93→    mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
 94→    for (int i = 0; i < 4; i++) {
 95→      v += a * noise(p);
 96→      p = rot * p * 2.0 + shift;
 97→      a *= 0.5;
 98→    }
 99→    return v;
100→  }
101→
102→  // --- glitch ---
103→  float glitchBlock(float y, float t) {
104→    float band = floor(y * 12.0);
105→    float trigger = hash(vec2(band, floor(t * 3.0)));
106→    float on = step(0.92, trigger);
107→    float offset = (hash(vec2(band, floor(t * 7.0))) - 0.5) * 2.0;
108→    return offset * on;
109→  }
110→
111→  // --- corruption scanlines (commented out for now) ---
112→  // float corruptionLine(float y, float t) {
113→  //   float band = floor(y * 40.0);
114→  //   float trigger = hash(vec2(band, floor(t * 4.0)));
115→  //   return step(0.97, trigger);
116→  // }
117→
118→  // --- character drawing ---
119→  float drawGlyph(vec2 cellUv, int idx) {
120→    float d = 0.0;
121→    vec2 c = cellUv - 0.5;
122→
123→    if (idx == 0) {
124→      d = smoothstep(0.15, 0.1, length(c));
125→    } else if (idx == 1) {
126→      d = smoothstep(0.06, 0.02, abs(c.y)) * smoothstep(0.35, 0.25, abs(c.x));
127→    } else if (idx == 2) {
128→      d = smoothstep(0.06, 0.02, abs(c.x)) * smoothstep(0.35, 0.25, abs(c.y));
129→    } else if (idx == 3) {
130→      float h = smoothstep(0.06, 0.02, abs(c.y)) * smoothstep(0.35, 0.25, abs(c.x));
131→      float v = smoothstep(0.06, 0.02, abs(c.x)) * smoothstep(0.35, 0.25, abs(c.y));
132→      d = max(h, v);
133→    } else if (idx == 4) {
134→      float d1 = smoothstep(0.12, 0.08, length(c - vec2(0.0, 0.18)));
135→      float d2 = smoothstep(0.12, 0.08, length(c + vec2(0.0, 0.18)));
136→      d = max(d1, d2);
137→    } else if (idx == 5) {
138→      float h1 = smoothstep(0.04, 0.01, abs(c.y - 0.15)) * smoothstep(0.35, 0.25, abs(c.x));
139→      float h2 = smoothstep(0.04, 0.01, abs(c.y + 0.15)) * smoothstep(0.35, 0.25, abs(c.x));
140→      float v1 = smoothstep(0.04, 0.01, abs(c.x - 0.15)) * smoothstep(0.35, 0.25, abs(c.y));
141→      float v2 = smoothstep(0.04, 0.01, abs(c.x + 0.15)) * smoothstep(0.35, 0.25, abs(c.y));
142→      d = max(max(h1, h2), max(v1, v2));
143→    } else if (idx == 6) {
144→      vec2 ac = abs(c);
145→      float box = smoothstep(0.32, 0.28, max(ac.x, ac.y)) - smoothstep(0.24, 0.2, max(ac.x, ac.y));
146→      d = max(box, 0.0);
147→    } else {
148→      vec2 ac = abs(c);
149→      d = smoothstep(0.32, 0.28, max(ac.x, ac.y));
150→    }
151→
152→    return d;
153→  }
154→
155→  float asciiField(vec2 uv, float cellSize, float t, float energyBoost) {
156→    vec2 cells = uResolution / cellSize;
157→    vec2 gridPos = uv * cells;
158→    vec2 cellId = floor(gridPos);
159→    vec2 cellUv = fract(gridPos);
160→
161→    float td = t * 0.08;
162→    vec2 noiseCoord = cellId * 0.06 + vec2(td * 0.7, td * 0.3);
163→    float n = fbm(noiseCoord);
164→    float n2 = fbm(noiseCoord * 1.5 + vec2(50.0));
165→    float intensity = n * 0.7 + n2 * 0.3;
166→
167→    // boost from mouse energy
168→    intensity += energyBoost * 0.3;
169→
170→    // vignette
171→    vec2 vc = uv - 0.5;
172→    float vignette = 1.0 - dot(vc, vc) * 1.8;
173→    intensity *= clamp(vignette, 0.0, 1.0);
174→
175→    int glyphIdx = 0;
176→    if (intensity < 0.2) glyphIdx = 0;
177→    else if (intensity < 0.3) glyphIdx = 1;
178→    else if (intensity < 0.38) glyphIdx = 4;
179→    else if (intensity < 0.46) glyphIdx = 2;
180→    else if (intensity < 0.54) glyphIdx = 3;
181→    else if (intensity < 0.62) glyphIdx = 5;
182→    else if (intensity < 0.72) glyphIdx = 6;
183→    else glyphIdx = 7;
184→
185→    float glyph = drawGlyph(cellUv, glyphIdx);
186→    return glyph * intensity;
187→  }
188→
189→  void main() {
190→    float cellSize = 14.0;
191→    float t = uTime;
192→
193→    // --- glitch: horizontal displacement ---
194→    vec2 uv = vUv;
195→    float glitchAmt = glitchBlock(uv.y, t);
196→    uv.x += glitchAmt * 0.03;
197→    uv.x = clamp(uv.x, 0.0, 1.0);
198→
199→    // --- read mouse energy texture ---
200→    float energy = texture2D(uEnergyTex, uv).r;
201→    energy = clamp(energy, 0.0, 1.0);
202→
203→    // --- main ascii field with energy boost ---
204→    float field = asciiField(uv, cellSize, t, energy);
205→
206→    // --- glow: sample neighbors ---
207→    float glowRadius = 3.0 / max(uResolution.x, uResolution.y);
208→    float glow = 0.0;
209→    glow += asciiField(uv + vec2( glowRadius,  0.0), cellSize, t, energy);
210→    glow += asciiField(uv + vec2(-glowRadius,  0.0), cellSize, t, energy);
211→    glow += asciiField(uv + vec2( 0.0,  glowRadius), cellSize, t, energy);
212→    glow += asciiField(uv + vec2( 0.0, -glowRadius), cellSize, t, energy);
213→    glow += asciiField(uv + vec2( glowRadius,  glowRadius) * 0.7, cellSize, t, energy);
214→    glow += asciiField(uv + vec2(-glowRadius,  glowRadius) * 0.7, cellSize, t, energy);
215→    glow += asciiField(uv + vec2( glowRadius, -glowRadius) * 0.7, cellSize, t, energy);
216→    glow += asciiField(uv + vec2(-glowRadius, -glowRadius) * 0.7, cellSize, t, energy);
217→    glow /= 8.0;
218→
219→    float combined = field + glow * 0.6;
220→
221→    // color
222→    vec3 orange = vec3(0.95, 0.45, 0.05);
223→    vec3 dimOrange = vec3(0.6, 0.25, 0.02);
224→    vec3 brightOrange = vec3(1.0, 0.7, 0.3);
225→
226→    vec2 vc = uv - 0.5;
227→    float vignette = clamp(1.0 - dot(vc, vc) * 1.8, 0.0, 1.0);
228→
229→    vec3 col = mix(dimOrange, orange, vignette * combined);
230→
231→    // glow bloom
232→    vec3 glowCol = mix(orange, brightOrange, 0.3);
233→    vec3 litCol = mix(col, glowCol, glow * 0.4);
234→
235→    // mouse energy: warm accent where cursor has been
236→    litCol = mix(litCol, brightOrange, energy * 0.25);
237→
238→    float alpha = combined * 0.35;
239→    alpha = mix(alpha, min(combined * 0.5, 1.0), energy * 0.18);
240→
241→    // --- corruption scanlines (commented out) ---
242→    // float corrupt = corruptionLine(vUv.y, t);
243→    // litCol = mix(litCol, vec3(1.0, 0.6, 0.1), corrupt * 0.8);
244→    // alpha = mix(alpha, 0.5, corrupt * 0.6);
245→
246→    // --- glitch: rgb split ---
247→    float glitchPresence = clamp(abs(glitchAmt) * 10.0, 0.0, 1.0);
248→    if (glitchPresence > 0.01) {
249→      float split = 0.004 * glitchPresence;
250→      float fieldR = asciiField(uv + vec2(split, 0.0), cellSize, t, energy);
251→      float fieldB = asciiField(uv - vec2(split, 0.0), cellSize, t, energy);
252→      litCol.r = mix(litCol.r, fieldR * orange.r * 1.5, glitchPresence * 0.7);
253→      litCol.b = mix(litCol.b, fieldB * 0.4, glitchPresence * 0.5);
254→      alpha = mix(alpha, alpha * 1.8, glitchPresence * 0.5);
255→    }
256→
257→    vec3 bg = vec3(0.04, 0.04, 0.04);
258→    vec3 final = mix(bg, litCol, alpha);
259→
260→    gl_FragColor = vec4(final, 1.0);
261→  }
262→`;
