264→// ---------- ping-pong FBO helper ----------
265→class DoubleFBO {
266→  read: THREE.WebGLRenderTarget;
267→  write: THREE.WebGLRenderTarget;
268→
269→  constructor(w: number, h: number) {
270→    const opts: THREE.RenderTargetOptions = {
271→      minFilter: THREE.LinearFilter,
272→      magFilter: THREE.LinearFilter,
273→      format: THREE.RGBAFormat,
274→      type: THREE.FloatType,
275→    };
276→    this.read = new THREE.WebGLRenderTarget(w, h, opts);
277→    this.write = new THREE.WebGLRenderTarget(w, h, opts);
278→  }
279→
280→  swap() {
281→    const tmp = this.read;
282→    this.read = this.write;
283→    this.write = tmp;
284→  }
285→
286→  dispose() {
287→    this.read.dispose();
288→    this.write.dispose();
289→  }
290→}
291→
292→// ---------- main scene component ----------
293→function ShaderPlane() {
294→  const meshRef = useRef<THREE.Mesh>(null);
295→  const { gl, size } = useThree();
296→
297→  // mouse state
298→  const mouseRef = useRef({
299→    x: 0,
300→    y: 0,
301→    prevX: 0,
302→    prevY: 0,
303→    moving: false,
304→    lastMoveTime: 0,
305→  });
306→
307→  // energy field FBOs (lower res for perf)
308→  const fboSize = 256;
309→  const energyFBO = useMemo(() => new DoubleFBO(fboSize, fboSize), []);
310→
311→  // offscreen scenes + materials for splat & decay passes
312→  const splatScene = useMemo(() => new THREE.Scene(), []);
313→  const decayScene = useMemo(() => new THREE.Scene(), []);
314→  const orthoCamera = useMemo(
315→    () => new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1),
316→    []
317→  );
318→
319→  const splatMaterial = useMemo(
320→    () =>
321→      new THREE.ShaderMaterial({
322→        vertexShader: fullscreenVert,
323→        fragmentShader: splatFrag,
324→        uniforms: {
325→          uPrev: { value: null },
326→          uSplatPos: { value: new THREE.Vector2(0.5, 0.5) },
327→          uSplatVel: { value: new THREE.Vector2(0, 0) },
328→          uSplatRadius: { value: 0.015 },
329→          uSplatStrength: { value: 0.025 },
330→          uDoSplat: { value: 0.0 },
331→        },
332→      }),
333→    []
334→  );
335→
336→  const decayMaterial = useMemo(
337→    () =>
338→      new THREE.ShaderMaterial({
339→        vertexShader: fullscreenVert,
340→        fragmentShader: decayFrag,
341→        uniforms: {
342→          uPrev: { value: null },
343→          uTexelSize: {
344→            value: new THREE.Vector2(1 / fboSize, 1 / fboSize),
345→          },
346→          uDecay: { value: 0.985 },
347→        },
348→      }),
349→    []
350→  );
351→
352→  // build offscreen scenes once
353→  useEffect(() => {
354→    const geo = new THREE.PlaneGeometry(2, 2);
355→
356→    const splatMesh = new THREE.Mesh(geo, splatMaterial);
357→    splatScene.add(splatMesh);
358→
359→    const decayMesh = new THREE.Mesh(geo, decayMaterial);
360→    decayScene.add(decayMesh);
361→
362→    return () => {
363→      energyFBO.dispose();
364→      geo.dispose();
365→      splatMaterial.dispose();
366→      decayMaterial.dispose();
367→    };
368→  }, [splatScene, decayScene, splatMaterial, decayMaterial, energyFBO]);
369→
370→  // display uniforms
371→  const displayUniforms = useMemo(
372→    () => ({
373→      uTime: { value: 0 },
374→      uResolution: { value: new THREE.Vector2(size.width, size.height) },
375→      uEnergyTex: { value: energyFBO.read.texture },
376→    }),
377→    // eslint-disable-next-line react-hooks/exhaustive-deps
378→    []
379→  );
380→
381→  // mouse handler
382→  const onPointerMove = useCallback((e: PointerEvent) => {
383→    const m = mouseRef.current;
384→    m.prevX = m.x;
385→    m.prevY = m.y;
386→    m.x = e.clientX / window.innerWidth;
387→    m.y = 1.0 - e.clientY / window.innerHeight; // flip y for GL
388→    m.moving = true;
389→    m.lastMoveTime = performance.now();
390→  }, []);
391→
392→  useEffect(() => {
393→    window.addEventListener("pointermove", onPointerMove);
394→    return () => window.removeEventListener("pointermove", onPointerMove);
395→  }, [onPointerMove]);
396→
397→  // render loop
398→  useFrame(({ clock }) => {
399→    if (!meshRef.current) return;
400→    const t = clock.getElapsedTime();
401→    const m = mouseRef.current;
402→
403→    // fade out splat if mouse stopped
404→    const timeSinceMove = performance.now() - m.lastMoveTime;
405→    const doSplat = timeSinceMove < 100 ? 1.0 : 0.0;
406→
407→    // --- splat pass ---
408→    splatMaterial.uniforms.uPrev.value = energyFBO.read.texture;
409→    splatMaterial.uniforms.uSplatPos.value.set(m.x, m.y);
410→    splatMaterial.uniforms.uSplatVel.value.set(
411→      m.x - m.prevX,
412→      m.y - m.prevY
413→    );
414→    splatMaterial.uniforms.uDoSplat.value = doSplat;
415→
416→    gl.setRenderTarget(energyFBO.write);
417→    gl.render(splatScene, orthoCamera);
418→    energyFBO.swap();
419→
420→    // --- decay pass ---
421→    decayMaterial.uniforms.uPrev.value = energyFBO.read.texture;
422→
423→    gl.setRenderTarget(energyFBO.write);
424→    gl.render(decayScene, orthoCamera);
425→    energyFBO.swap();
426→
427→    // --- display pass ---
428→    gl.setRenderTarget(null);
429→    const mat = meshRef.current.material as THREE.ShaderMaterial;
430→    mat.uniforms.uTime.value = t;
431→    mat.uniforms.uResolution.value.set(size.width, size.height);
432→    mat.uniforms.uEnergyTex.value = energyFBO.read.texture;
433→  });
434→
435→  return (
436→    <mesh ref={meshRef}>
437→      <planeGeometry args={[2, 2]} />
438→      <shaderMaterial
439→        vertexShader={fullscreenVert}
440→        fragmentShader={displayFrag}
441→        uniforms={displayUniforms}
442→      />
443→    </mesh>
444→  );
445→}
