447→export function AsciiBackground() {
448→  return (
449→    <div className="fixed inset-0 -z-10">
450→      <Canvas
451→        gl={{ antialias: false, alpha: false }}
452→        camera={{ position: [0, 0, 1] }}
453→        dpr={[1, 1.5]}
454→        style={{ width: "100%", height: "100%" }}
455→      >
456→        <ShaderPlane />
457→      </Canvas>
458→    </div>
459→  );
460→}
