  3→/**
  4→ * Sidebar listing all agents with status dots, truncated labels,
  5→ * tmux session names, and a "+" button to spawn a new agent.
  6→ *
  7→ * Split into two sections:
  8→ * - **Active**: agents with status `spawning`, `connected`, or `thinking`.
  9→ * - **Archived**: agents with status `done`, `disconnected`, or `error` (read-only).
 10→ *
 11→ * Right-click (or kebab icon) context menu supports: Rename, Kill, Clear History, Delete.
 12→ * Rename swaps the label for an inline input.
 13→ */
 14→
 15→import { useCallback, useEffect, useRef, useState } from "react";
 16→import { EllipsisVertical, Plus } from "lucide-react";
 17→import type { AgentStatus } from "@/lib/types";
 18→import type { AgentClientState } from "@/hooks/use-websocket";
 19→import { cn } from "@/lib/utils";
 20→
 21→/** Status dot color + optional pulse animation. */
 22→const STATUS_DOT: Record<AgentStatus, string> = {
 23→  idle: "bg-muted-foreground",
 24→  spawning: "bg-yellow-500 animate-pulse",
 25→  connected: "bg-green-500",
 26→  thinking: "bg-blue-500 animate-pulse",
 27→  done: "bg-muted-foreground",
 28→  disconnected: "bg-orange-500 animate-pulse",
 29→  error: "bg-red-500",
 30→};
 31→
 32→/** Statuses where the CLI is actively running and can be killed. */
 33→const KILLABLE: Set<AgentStatus> = new Set(["spawning", "connected", "thinking"]);
 34→/** Statuses considered archived (session ended, read-only). */
 35→const ARCHIVED: Set<AgentStatus> = new Set(["done", "disconnected", "error"]);
 36→
 37→interface ContextMenuState {
 38→  agentId: string;
 39→  x: number;
 40→  y: number;
 41→}
 42→
 43→export function AgentSidebar({
 44→  agents,
 45→  agentOrder,
 46→  activeAgentId,
 47→  onSelect,
 48→  onNewAgent,
 49→  onKill,
 50→  onDelete,
 51→  onRename,
 52→  onClearHistory,
 53→}: {
 54→  agents: Map<string, AgentClientState>;
 55→  agentOrder: string[];
 56→  activeAgentId: string | null;
 57→  onSelect: (agentId: string | null) => void;
 58→  onNewAgent: () => void;
 59→  onKill: (agentId: string) => void;
 60→  onDelete: (agentId: string) => void;
 61→  onRename: (agentId: string, label: string) => void;
 62→  onClearHistory: (agentId: string) => void;
 63→}) {
 64→  const [ctxMenu, setCtxMenu] = useState<ContextMenuState | null>(null);
 65→  const [renamingId, setRenamingId] = useState<string | null>(null);
 66→  const menuRef = useRef<HTMLDivElement>(null);
 67→
 68→  // Split agents into active and archived
 69→  const activeIds = agentOrder.filter((id) => {
 70→    const a = agents.get(id);
 71→    return a && !ARCHIVED.has(a.status);
 72→  });
 73→  const archivedIds = agentOrder.filter((id) => {
 74→    const a = agents.get(id);
 75→    return a && ARCHIVED.has(a.status);
 76→  });
 77→
 78→  // Close context menu on click-outside or Escape
 79→  useEffect(() => {
 80→    if (!ctxMenu) return;
 81→    function handleClick(e: MouseEvent) {
 82→      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
 83→        setCtxMenu(null);
 84→      }
 85→    }
 86→    function handleKey(e: KeyboardEvent) {
 87→      if (e.key === "Escape") setCtxMenu(null);
 88→    }
 89→    document.addEventListener("mousedown", handleClick);
 90→    document.addEventListener("keydown", handleKey);
 91→    return () => {
 92→      document.removeEventListener("mousedown", handleClick);
 93→      document.removeEventListener("keydown", handleKey);
 94→    };
 95→  }, [ctxMenu]);
 96→
 97→  const openMenu = useCallback((agentId: string, x: number, y: number) => {
 98→    setCtxMenu({ agentId, x, y });
 99→  }, []);
100→
101→  const handleContextMenu = useCallback((e: React.MouseEvent, agentId: string) => {
102→    e.preventDefault();
103→    openMenu(agentId, e.clientX, e.clientY);
104→  }, [openMenu]);
105→
106→  const handleMenuButton = useCallback((e: React.MouseEvent, agentId: string) => {
107→    e.stopPropagation();
108→    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
109→    openMenu(agentId, rect.right, rect.bottom);
110→  }, [openMenu]);
111→
112→  const closeMenu = useCallback(() => setCtxMenu(null), []);
113→
114→  function renderAgentRow(id: string, archived: boolean) {
115→    const agent = agents.get(id);
116→    if (!agent) return null;
117→    const isActive = id === activeAgentId;
118→    return (
119→      <div
120→        key={id}
121→        onClick={() => onSelect(id)}
122→        onContextMenu={(e) => handleContextMenu(e, id)}
123→        className={cn(
124→          "group flex w-full cursor-pointer items-start gap-0.5 px-3 py-2 text-left text-xs transition-colors",
125→          isActive ? "bg-sidebar-accent" : "hover:bg-sidebar-accent/50",
126→          archived && "opacity-60"
127→        )}
128→      >
129→        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
130→          <span className="flex items-center gap-2">
131→            <span className={cn("inline-block size-2 shrink-0 rounded-full", STATUS_DOT[agent.status])} />
132→            {renamingId === id ? (
133→              <RenameInput
134→                initialValue={agent.label}
135→                onConfirm={(label) => {
136→                  onRename(id, label);
137→                  setRenamingId(null);
138→                }}
139→                onCancel={() => setRenamingId(null)}
140→              />
141→            ) : (
142→              <span className="truncate">{agent.label || "new agent"}</span>
143→            )}
144→          </span>
145→          {agent.tmuxSession && (
146→            <span className="pl-4 text-[10px] text-muted-foreground truncate">
147→              {agent.tmuxSession}
148→            </span>
149→          )}
150→        </div>
151→        <button
152→          onClick={(e) => handleMenuButton(e, id)}
153→          className="shrink-0 rounded p-0.5 opacity-0 transition-opacity hover:bg-sidebar-accent group-hover:opacity-100"
154→          aria-label="Agent menu"
155→        >
156→          <EllipsisVertical className="size-3.5 text-muted-foreground" />
157→        </button>
158→      </div>
159→    );
160→  }
161→
162→  return (
163→    <div className="flex w-56 flex-col border-r bg-sidebar text-sidebar-foreground">
164→      {/* Header */}
165→      <div className="flex items-center justify-between border-b px-3 py-2">
166→        <span className="text-xs font-semibold">agents</span>
167→        <button
168→          onClick={onNewAgent}
169→          className="rounded-md p-1 hover:bg-sidebar-accent transition-colors"
170→          aria-label="New agent"
171→        >
172→          <Plus className="size-3.5" />
173→        </button>
174→      </div>
175→
176→      {/* Agent list */}
177→      <div className="flex-1 overflow-y-auto">
178→        {agentOrder.length === 0 && (
179→          <div className="px-3 py-4 text-xs text-muted-foreground">
180→            No agents yet
181→          </div>
182→        )}
183→
184→        {/* Active agents */}
185→        {activeIds.map((id) => renderAgentRow(id, false))}
186→
187→        {/* Archived divider + agents */}
188→        {archivedIds.length > 0 && (
189→          <>
190→            <div className="flex items-center gap-2 px-3 pt-3 pb-1">
191→              <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">archived</span>
192→              <div className="flex-1 border-t" />
193→            </div>
194→            {archivedIds.map((id) => renderAgentRow(id, true))}
195→          </>
196→        )}
197→      </div>
198→
199→      {/* Context menu */}
200→      {ctxMenu && (() => {
201→        const agent = agents.get(ctxMenu.agentId);
202→        if (!agent) return null;
203→        return (
204→          <div
205→            ref={menuRef}
206→            className="fixed z-50 min-w-[160px] rounded-md border bg-popover py-1 text-popover-foreground shadow-md"
207→            style={{ left: ctxMenu.x, top: ctxMenu.y }}
208→          >
209→            <ContextMenuItem
210→              label="Rename"
211→              onClick={() => {
212→                setRenamingId(ctxMenu.agentId);
213→                closeMenu();
214→              }}
215→            />
216→            {KILLABLE.has(agent.status) && (
217→              <ContextMenuItem
218→                label="Kill"
219→                onClick={() => {
220→                  onKill(ctxMenu.agentId);
221→                  closeMenu();
222→                }}
223→              />
224→            )}
225→            <ContextMenuItem
226→              label="Clear History"
227→              onClick={() => {
228→                onClearHistory(ctxMenu.agentId);
229→                closeMenu();
230→              }}
231→            />
232→            <div className="my-1 border-t" />
233→            <ContextMenuItem
234→              label="Delete"
235→              destructive
236→              onClick={() => {
237→                closeMenu();
238→                if (confirm("Delete this agent? This cannot be undone.")) {
239→                  onDelete(ctxMenu.agentId);
240→                }
241→              }}
242→            />
243→          </div>
244→        );
245→      })()}
246→    </div>
247→  );
248→}
249→
250→/** A single item in the context menu. */
251→function ContextMenuItem({
252→  label,
253→  onClick,
254→  destructive,
255→}: {
256→  label: string;
257→  onClick: () => void;
258→  destructive?: boolean;
259→}) {
260→  return (
261→    <button
262→      onClick={onClick}
263→      className={cn(
264→        "flex w-full px-3 py-1.5 text-xs transition-colors",
265→        destructive
266→          ? "text-red-500 hover:bg-red-500/10"
267→          : "hover:bg-accent"
268→      )}
269→    >
270→      {label}
271→    </button>
272→  );
273→}
274→
275→/** Inline input for renaming an agent. */
276→function RenameInput({
277→  initialValue,
278→  onConfirm,
279→  onCancel,
280→}: {
281→  initialValue: string;
282→  onConfirm: (value: string) => void;
283→  onCancel: () => void;
284→}) {
285→  const [value, setValue] = useState(initialValue);
286→  const inputRef = useRef<HTMLInputElement>(null);
287→
288→  useEffect(() => {
289→    inputRef.current?.focus();
290→    inputRef.current?.select();
291→  }, []);
292→
293→  function handleKeyDown(e: React.KeyboardEvent) {
294→    e.stopPropagation();
295→    if (e.key === "Enter") {
296→      const trimmed = value.trim();
297→      if (trimmed) onConfirm(trimmed);
298→      else onCancel();
299→    } else if (e.key === "Escape") {
300→      onCancel();
301→    }
302→  }
303→
304→  return (
305→    <input
306→      ref={inputRef}
307→      type="text"
308→      value={value}
309→      onChange={(e) => setValue(e.target.value)}
310→      onKeyDown={handleKeyDown}
311→      onBlur={() => {
312→        const trimmed = value.trim();
313→        if (trimmed && trimmed !== initialValue) onConfirm(trimmed);
314→        else onCancel();
315→      }}
316→      onClick={(e) => e.stopPropagation()}
317→      className="flex-1 rounded border bg-background px-1 py-0 text-xs outline-none focus:ring-1 focus:ring-ring"
318→    />
319→  );
320→}
