  1→/**
  2→ * Shared type definitions for the thos dashboard.
  3→ *
  4→ * Three categories:
  5→ * 1. **Claude NDJSON protocol** — messages the Claude CLI sends over its
  6→ *    `--sdk-url` WebSocket connection (CLI → WS server).
  7→ * 2. **Browser ↔ Server** — messages exchanged between the React client
  8→ *    and the standalone WS relay server.
  9→ * 3. **UI state** — view-model types consumed by React components.
 10→ */
 11→
 12→// ── Claude NDJSON protocol messages (CLI → server) ────────────────────────
 13→
 14→/**
 15→ * Sent once after the first user prompt is received. Contains session
 16→ * metadata like the model name, working directory, and available tools.
 17→ */
 18→export interface ClaudeSystemInit {
 19→  type: "system";
 20→  subtype: "init";
 21→  session_id: string;
 22→  tools: unknown[];
 23→  mcp_servers: unknown[];
 24→  model: string;
 25→  cwd: string;
 26→}
 27→
 28→/**
 29→ * An assistant turn. `message.content` is an array of content blocks
 30→ * (text, tool_use, tool_result) that may arrive incrementally — each
 31→ * NDJSON line is a complete snapshot of the message so far.
 32→ */
 33→export interface ClaudeAssistant {
 34→  type: "assistant";
 35→  message: {
 36→    id: string;
 37→    role: "assistant";
 38→    content: AssistantContentBlock[];
 39→    model: string;
 40→    stop_reason: string | null;
 41→  };
 42→  session_id: string;
 43→}
 44→
 45→/** A single content block inside an assistant message. */
 46→export type AssistantContentBlock =
 47→  | { type: "text"; text: string }
 48→  | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
 49→  | { type: "tool_result"; tool_use_id: string; content: string };
 50→
 51→/**
 52→ * Terminal message for a session. Includes cost/duration metrics.
 53→ * `is_error` is true when `subtype` is `"error"`.
 54→ */
 55→export interface ClaudeResult {
 56→  type: "result";
 57→  subtype: "success" | "error";
 58→  result?: string;
 59→  error?: string;
 60→  session_id: string;
 61→  cost_usd: number;
 62→  duration_ms: number;
 63→  duration_api_ms: number;
 64→  is_error: boolean;
 65→  num_turns: number;
 66→}
 67→
 68→/**
 69→ * Claude is requesting permission to execute a tool. The dashboard must
 70→ * reply with a `control_response` (allow / deny) before the CLI proceeds.
 71→ *
 72→ * Wire format uses a nested `request` object with `request_id` at the
 73→ * top level for correlation (matches Companion protocol docs).
 74→ */
 75→export interface ClaudeControlRequest {
 76→  type: "control_request";
 77→  request_id: string;
 78→  request: {
 79→    subtype: "can_use_tool";
 80→    tool_name: string;
 81→    input: Record<string, unknown>;
 82→    tool_use_id?: string;
 83→    description?: string;
 84→  };
 85→  session_id?: string;
 86→}
 87→
 88→/**
 89→ * Hook lifecycle events emitted during CLI startup. `hook_response` is
 90→ * the signal that the CLI is ready to receive the first user prompt.
 91→ */
 92→export interface ClaudeSystemHook {
 93→  type: "system";
 94→  subtype: "hook_started" | "hook_response";
 95→  session_id?: string;
 96→}
 97→
 98→/** Discriminated union of all known Claude NDJSON message shapes. */
 99→export type ClaudeMessage =
100→  | ClaudeSystemInit
101→  | ClaudeAssistant
102→  | ClaudeResult
103→  | ClaudeControlRequest
104→  | ClaudeSystemHook
105→  | { type: string; subtype?: string; [key: string]: unknown };
106→
107→// ── Browser ↔ Server messages ─────────────────────────────────────────────
108→
109→/** Browser asks the server to spawn a new Claude CLI process. */
110→export interface BrowserSpawn {
111→  type: "spawn";
112→  prompt: string;
113→}
114→
115→/** Browser sends a follow-up message to an already-running Claude session. */
116→export interface BrowserSendMessage {
117→  type: "send_message";
118→  agentId: string;
119→  content: string;
120→}
121→
122→/** Browser responds to a tool approval request (allow or deny). */
123→export interface BrowserControlResponse {
124→  type: "control_response";
125→  agentId: string;
126→  request_id: string;
127→  allow: boolean;
128→}
129→
130→/** Browser asks the server to kill a running agent's tmux session + CLI. */
131→export interface BrowserKillAgent {
132→  type: "kill_agent";
133→  agentId: string;
134→}
135→
136→/** Browser asks the server to permanently delete an agent. */
137→export interface BrowserDeleteAgent {
138→  type: "delete_agent";
139→  agentId: string;
140→}
141→
142→/** Browser asks the server to rename an agent. */
143→export interface BrowserRenameAgent {
144→  type: "rename_agent";
145→  agentId: string;
146→  label: string;
147→}
148→
149→/** Browser asks the server to clear an agent's message history. */
150→export interface BrowserClearHistory {
151→  type: "clear_history";
152→  agentId: string;
153→}
154→
155→/** Union of all messages the browser can send to the WS server. */
156→export type BrowserMessage =
157→  | BrowserSpawn
158→  | BrowserSendMessage
159→  | BrowserControlResponse
160→  | BrowserKillAgent
161→  | BrowserDeleteAgent
162→  | BrowserRenameAgent
163→  | BrowserClearHistory;
164→
165→/** Server relays a raw Claude NDJSON message to the browser. */
166→export interface ServerRelay {
167→  type: "relay";
168→  agentId: string;
169→  message: ClaudeMessage;
170→}
171→
172→/** Server notifies the browser of an agent status change. */
173→export interface ServerStatus {
174→  type: "status";
175→  agentId: string;
176→  status: AgentStatus;
177→}
178→
179→/** Server reports an error (e.g. no active session, process crash). */
180→export interface ServerError {
181→  type: "error";
182→  agentId: string;
183→  error: string;
184→}
185→
186→/** Summary of an agent for the sidebar. */
187→export interface AgentInfo {
188→  agentId: string;
189→  status: AgentStatus;
190→  tmuxSession: string | null;
191→  label: string;
192→  createdAt: number;
193→}
194→
195→/** Server sends the full list of agents after every state change. */
196→export interface ServerAgentList {
197→  type: "agent_list";
198→  agents: AgentInfo[];
199→}
200→
201→/** Server confirms a new agent was spawned and assigns its ID. */
202→export interface ServerSpawned {
203→  type: "spawned";
204→  agentId: string;
205→}
206→
207→/** Server replays full message history for an agent on browser connect. */
208→export interface ServerMessageHistory {
209→  type: "message_history";
210→  agentId: string;
211→  messages: ServerMessage[];
212→}
213→
214→/** CLI WebSocket disconnected (process may have crashed or exited). */
215→export interface ServerCliDisconnected {
216→  type: "cli_disconnected";
217→  agentId: string;
218→}
219→
220→/** CLI WebSocket reconnected (e.g. after relaunch with --resume). */
221→export interface ServerCliConnected {
222→  type: "cli_connected";
223→  agentId: string;
224→}
225→
226→/** Server confirms message history was cleared for an agent. */
227→export interface ServerHistoryCleared {
228→  type: "history_cleared";
229→  agentId: string;
230→}
231→
232→/** Union of all messages the WS server can send to the browser. */
233→export type ServerMessage =
234→  | ServerRelay
235→  | ServerStatus
236→  | ServerError
237→  | ServerAgentList
238→  | ServerSpawned
239→  | ServerMessageHistory
240→  | ServerCliDisconnected
241→  | ServerCliConnected
242→  | ServerHistoryCleared;
243→
244→// ── UI state ──────────────────────────────────────────────────────────────
245→
246→/**
247→ * Lifecycle states of the Claude agent process:
248→ * - `idle`      — no process running, ready to spawn
249→ * - `spawning`  — process launched, waiting for CLI to connect via WS
250→ * - `connected` — CLI connected and `system/init` received
251→ * - `thinking`  — waiting for assistant response
252→ * - `done`      — `result` message received, process finished
253→ * - `error`     — process crashed or unexpected failure
254→ */
255→export type AgentStatus = "idle" | "spawning" | "connected" | "thinking" | "done" | "disconnected" | "error";
256→
257→export type ChatMessageRole = "user" | "assistant" | "system";
258→
259→/**
260→ * A single entry in the chat message list. System messages include
261→ * session init info and result summaries. Messages with a `controlRequest`
262→ * are rendered as tool-approval cards instead of plain bubbles.
263→ */
264→/** A single option in an AskUserQuestion question. */
265→export interface UserQuestionOption {
266→  label: string;
267→  description?: string;
268→}
269→
270→/** A single question from AskUserQuestion. */
271→export interface UserQuestion {
272→  question: string;
273→  header?: string;
274→  options: UserQuestionOption[];
275→  multiSelect: boolean;
276→}
277→
278→/** Info about a single tool_use block in an assistant message. */
279→export interface ToolCallInfo {
280→  name: string;
281→  toolUseId?: string;
282→}
283→
284→export interface ChatMessage {
285→  id: string;
286→  role: ChatMessageRole;
287→  content: string;
288→  timestamp: number;
289→  /** Present when this message represents a tool approval request. */
290→  controlRequest?: {
291→    id: string;
292→    tool_name: string;
293→    input: Record<string, unknown>;
294→    /** Set to true after the user allows or denies. */
295→    resolved?: boolean;
296→  };
297→  /** Present when this message is an AskUserQuestion control request. */
298→  userQuestion?: {
299→    requestId: string;
300→    questions: UserQuestion[];
301→    resolved?: boolean;
302→  };
303→  /** Tool calls found in this assistant message. */
304→  toolCalls?: ToolCallInfo[];
305→  /** True when this message has only tool_use/tool_result blocks and no text. */
306→  isToolOnly?: boolean;
307→}
308→

/**
 * Standalone WebSocket relay server for the thos dashboard.
 *
 * Runs on port 9900 alongside Next.js (started via `concurrently` in the
 * `dev` script). It cannot be a Next.js API route because API routes don't
 * support persistent WebSocket connections.
 *
 * ## Architecture
 *
 * Two WebSocket path families:
 * - `/browser`          — the React dashboard connects here (supports multiple tabs).
 * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
 *
 * The server supports multiple concurrent agents, each tracked in the
 * `agents` Map keyed by a short random ID.
 *
 * ## Resilience features
 *
 * - **Server-side message history** — every relay message is stored per-agent.
 * - **File persistence** — agent state + history persisted to disk, survives restarts.
 * - **Multi-browser** — multiple tabs can connect simultaneously.
 * - **tmux survival** — tmux sessions are NOT killed on server restart; CLI processes
 *   can reconnect to the new server if they retry their WebSocket connection.
 * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
 * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
 *
 * ## Message flow
 *
 * 1. Browser sends `{ type: "spawn", prompt }`.
 * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
 * 3. CLI connects on `/claude/<agentId>`, sends `system/hook_started` then `system/hook_response`.
 * 4. On `hook_response`, server forwards the pending prompt to the CLI.
 * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
 * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
 * 7. `control_request` messages (tool approval) are relayed to the browser;
 *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
 */
import { WebSocketServer, WebSocket } from "ws";
import { execSync, spawn } from "child_process";
import { randomBytes } from "crypto";
import type { IncomingMessage } from "http";
import type {
  BrowserMessage,
  ClaudeMessage,
  ServerMessage,
  AgentStatus,
  AgentInfo,
} from "../lib/types";
import { SessionStore, type PersistedAgent } from "./session-store";

const PORT = 9900;
const TMUX_SESSION_PREFIX = "thos-agent";
const wss = new WebSocketServer({ port: PORT });
const store = new SessionStore();

// ── Multi-agent state ──────────────────────────────────────────────────────

interface AgentState {
  agentId: string;
  claudeSocket: WebSocket | null;
  tmuxSession: string | null;
  pendingPrompt: string | null;
  status: AgentStatus;
  label: string;
  createdAt: number;
  /** Captured from system/init, used in subsequent user messages. */
  sessionId: string | null;
  /** Stores control_request inputs keyed by request_id, for building control_responses. */
  pendingControlRequests: Map<string, Record<string, unknown>>;
  /** All messages sent to the browser for this agent (source of truth). */
  messageHistory: ServerMessage[];
  /** Messages queued while CLI is disconnected, flushed on reconnect. */
  pendingMessages: string[];
}

const agents = new Map<string, AgentState>();

/** All active browser connections (supports multiple tabs). */
const browserSockets = new Set<WebSocket>();

/** Generate a short random agent ID. */
function newAgentId(): string {
  return randomBytes(4).toString("hex");
}

// ── tmux helpers ───────────────────────────────────────────────────────────

/** Return the set of currently alive tmux session names matching the thos prefix. */
function listAliveTmuxSessions(): Set<string> {
  try {
    const output = execSync("tmux list-sessions -F '#{session_name}'", {
      encoding: "utf-8",
    }).trim();
    if (!output) return new Set();
    return new Set(output.split("\n").filter((s) => s.startsWith(TMUX_SESSION_PREFIX)));
  } catch {
    return new Set();
  }
}

const config = {
  plugins: {
    "@tailwindcss/postcss": {},
  },
};

export default config;

